      "stem": "閱讀下列節錄自校園文學獎散文首獎的段落，回答問題：\n「夏午的溪谷是一座甦醒的劇場：① 蟬鳴在樟樹梢織成一張密不透風的銀網，亮晃晃地罩住整片山林；② 溪水撞擊鵝卵石，叮咚作響，濺起冰涼刺骨的碎玉；③ 野薑花清甜的芬芳順著山風漫開，連呼吸都染上一絲微甜；④ 我們在溪畔奔跑著，在石上歡呼著，在風裡揮灑著年少的汗水。」\n關於文中畫線處 ①～④ 句的「感官摹寫、譬喻轉化與排比修辭功能」判讀，下列敘述何者正確？",
