        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱閱讀理解歷程與證據層次（5-IV-2）：①「明示」為擷取文本表層直接寫出的客觀事實；②「推論」為串聯文本前後因果線索，推導出字面未直接點破的動機或隱含意義；③「反證」為運用文本確鑿紀錄去證偽、排除相矛盾的錯誤假設；④「評價」為跳脫故事內部，對文本的寫作技巧、結構美學或人物精神價值提出鑑賞判斷。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 分析小安發言：「產業道路五公里處遇到坍方落石」、「徒步」、「比平時晚了兩個鐘頭」全數可在原文第 2、3 句逐字圈出，未做任何延伸詮釋，屬於「明示」。\n2. 分析小芸發言：原文僅寫「看了一眼掛號信，便將雨衣反穿護住胸前郵包」與結尾「乾燥平整的信封」，並未直接寫出「為了防止大雨淋濕……」四字目的；小芸連結前後行動與結果導出林伯伯的用意，屬於「推論」。\n3. 分析小哲發言：針對「機車沒油才走路」的假設，直接引述原文「坍方落石擋住去路，機車無法通行」加以駁斥推翻，屬於標準的「反證」。\n4. 分析小彤發言：從讀者賞析角度評論作者「不喊空洞口號、透過強烈視覺對比、極具感染力地塑造職人形象」，屬於針對寫作手法與藝術效果的「評價」。\n四項依序為「明示 ／ 推論 ／ 反證 ／ 評價」，故正確選項為 (D)。",
