      "stem": "閱讀下列【甲文】與【乙表】兩則跨文本資料，回答問題：\n【甲文：青少年咖啡因攝取衛教專文】\n「咖啡因能暫時阻斷大腦中的腺苷受體，減少睡意，但過量攝取易引發心悸、焦慮並干擾深層睡眠。我國衛福部與兒科醫學會建議：12 至 18 歲青少年每日咖啡因總攝取量不宜超過『每公斤體重 2.5 毫克』，且單日上限以不超過 100 毫克為原則。此外，許多人以為只有黑咖啡含咖啡因，卻忽略茶飲、可樂與能量飲料同樣含有不等量的咖啡因。」\n【乙表：市售常見飲品咖啡因含量檢測表（2025 年消基會抽驗均值）】\n┌───────────┬────────┬───────────────┐\n│ 飲品品項         │ 單瓶／杯容量 │ 咖啡因含量（注意單位基準！）│\n├───────────┼────────┼───────────────┤\n│ 美式冰咖啡（中杯） │ 360 mL     │ 45 毫克 ／ 每 100 mL       │\n│ 濃韻烏龍茶（瓶裝） │ 500 mL     │ 18 毫克 ／ 每 100 mL       │\n│ 碳酸可樂（罐裝）   │ 330 mL     │ 32 毫克 ／ 整罐總量         │\n│ 提神能量飲（罐裝） │ 250 mL     │ 32 毫克 ／ 每 100 mL       │\n└───────────┴────────┴───────────────┘\n結合【甲文】規範與【乙表】單位基準進行跨文本互證，若一位 14 歲、體重 36 公斤的八年級學生想嚴格遵守衛教建議，下列判斷何者完全正確？",
