        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 計算該生（14 歲、36 公斤）的每日建議上限：依體重算為 36 × 2.5 ＝ 90 毫克；與單日封頂上限 100 毫克相比，同時滿足兩條件的上限即為「90 毫克」。\n2. 換算【乙表】四種飲品的「單瓶／整杯實際總咖啡因」：\n   • 美式冰咖啡（360 mL）：45 毫克 × (360 ÷ 100) ＝ 45 × 3.6 ＝ 162 毫克。\n   • 濃韻烏龍茶（500 mL）：18 毫克 × (500 ÷ 100) ＝ 18 × 5 ＝ 90 毫克。\n   • 碳酸可樂（330 mL）：單位明定為「整罐總量」，故一整罐 ＝ 32 毫克，半罐 ＝ 16 毫克。\n   • 提神能量飲（250 mL）：32 毫克 × (250 ÷ 100) ＝ 32 × 2.5 ＝ 80 毫克。\n3. 核對飲用組合：一瓶濃韻烏龍茶（90 毫克）＋ 半罐碳酸可樂（16 毫克）＝ 106 毫克 ＞ 個人建議上限 90 毫克（甚至也超過 100 毫克總上限），確已超標！故正確選項為 (A)。",
