        "【第 1 步：審題定位 · 題眼與已知】題幹為結構嚴謹的四段式（四層次）議論短文，標出【甲】、【乙】、【丙】、【丁】四個區塊，要求精準辨別何處為「論點」、何處為「道理論據／事實論據」，以及採用了哪幾種「論證方法」。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱議論文本結構原則（Bd-IV-1、Bd-IV-2）：① 論點常以「不在於 A，而在於 B」或「由此可見，唯有……才……」等明確價值判斷句呈現；② 引述經典名言屬「道理論據（引用論證）」；③ 同時舉出符合主張的正面典範與違背主張的反面弊病加以對照，屬「事實論據」結合「正反對比論證」。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 辨別論點位置：【甲】開門見山以「不在於……而在於……」界定閱讀素養的核心在於獨立查證與思辨；【丁】以「由此可見，唯有……才……」總結收束，兩句首尾呼應，共同構成全文中心「論點」。\n2. 辨別【乙】之論據與論證：引述孟子名言「盡信書，則不如無書」並闡釋其義，屬於「道理論據」，論證方法為「引用論證」。\n3. 辨別【丙】之論據與論證：前半段舉東漢王充實地考察寫成《論衡》為「正面事例」，後半段以「反觀」轉折，舉當代部分網友未經查證盲目轉發假訊息為「反面事例」，一正一反鮮明對照，屬於「事實論據」搭配「正反對比論證（兼舉例論證）」。故正確選項為 (B)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：【甲】句明確表達作者對「何謂真正閱讀素養」的價值主張，正是全文起首中心論點，絕非純客觀事實紀錄；【丙】句則是支撐論點的歷史與當代事例（論據），並非論點本身。\n• 選項 (C) 錯誤：孟子名言屬於「道理論據」而非量化統計數據；且【丙】句中間有明顯標誌詞「反觀」，清楚呈現一正一反兩組事例，並非單向正面舉例。\n• 選項 (D) 錯誤：觸犯本課核心迷思——「名人說過不等於證據充分」！古典格言雖能輔助說理，但在現代議題中仍須搭配具體事證與嚴密推理，不能把單一名人言論神化為無懈可擊的科學證明。",
