      "title": "【會考詩歌修辭原型改編】轉品詞性變換、借代特徵與象徵寄託界線精準辨析",
      "stem": "九年級詩歌賞析課整理出四組古典與現代詩文名句，探討詩人如何錘鍊字句以濃縮情感與意象：\n【甲】「春風又『綠』江南岸，明月何時照我還？」（王安石〈泊船瓜洲〉）\n【乙】「孤『帆』遠影碧空盡，唯見長江天際流。」（李白〈黃鶴樓送孟浩然之廣陵〉）\n【丙】「田園寥落『干戈』後，骨肉流離道路中。」（白居易〈望月有感〉）\n【丁】「母親啊！天上的風雨來了，鳥兒躲到它的巢裡；心中的『風雨』來了，我只躲到妳的懷裡。」（冰心《繁星》）\n依據本單元「特殊修辭：轉品、借代與象徵手法」的辨析界線，下列針對【甲】～【丁】四句的分析何者完全正確？",
