      "stem": "九年級會考寫作模擬測驗題目為「那一刻，我看見了微光」。國文老師展示甲、乙兩份學生習作草稿，引導全班從「篇章組織與材料經營」角度進行診斷：\n【甲生草稿】「自古以來，助人為快樂之本，雪中送炭更是光風霽月、高山仰止的美德。人生難免山窮水盡，只要有人披星戴月、赴湯蹈火地伸出援手，就能柳暗花明又一村。我們青少年應該見賢思齊、日日行善，讓社會處處充滿微光，所以我今天看見了微光，真是太感動了，我們大家一定要努力看見微光！」\n【乙生寫作大綱與摘錄】\n• 起段：以冬夜補習後驟雨濕冷、腳踏車落鏈受困昏暗騎樓的狼狽場景開篇，聚焦街角老修車行透出的一線昏黃燈光。\n• 承段（具體事件展開）：細寫滿手黑油漬的老闆默默遞來乾毛巾，蹲在冰涼積水邊逐節校準鏈條，分文未取只笑說「雨大，騎慢點」的動作與神情細節。\n• 轉段（由細節轉入反思）：由老闆指縫洗不掉的黑油漬與溫暖叮嚀，轉入內心省思——原來「微光」不必是驚天動地的英雄壯舉，陌生人之間不求回報的體貼善意，便足以驅散人心的焦躁與冷漠。\n• 合段（首尾呼應與昇華）：寫隔月自己在公車上主動將備用摺傘借給淋濕的學弟，呼應冬夜騎樓那盞黃光——原來曾被微光照亮的人，也能成為別人雨夜裡的一束光。\n依據 108 課綱寫作組織原則（6-IV-2），下列對甲、乙兩稿的評析何者完全正確？",
