        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 第一格：`Why + are + you + talking...?` 補齊進行式所需的 be 動詞 `are`。\n2. 第二格：真正主詞為單數 `Everyone`（刮除修飾片語 around you），當下正在讀書填單數進行式 `is studying`。\n3. 第三格：主詞 `My partner Leo` 為三單，動詞 `need` 為不可用進行式的狀態動詞，採用現在簡單式三單 `needs`。\n4. 三格依序為 `are; is studying; needs`，故正確選項為 (B)。",
