        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：犯了八年級段考最致命的「重複標記過去式」錯誤——`Did your sister went` 中 Did 與 went 雙重標記過去，違背助動詞後回原形的鐵律！\n• 選項 (B) 錯誤：`Was your sister go` 將過去式 be 動詞 Was 與原形一般動詞 go 硬湊在一起；be 動詞過去式僅能接形容詞、名詞、介系詞片語或分詞。\n• 選項 (C) 錯誤：第三格誤將「母音＋y」的 stay 當成「子音＋y」去 y 加 ied 寫成錯誤拼字 `staied`（同理 play → played、enjoy → enjoyed 皆不可去 y）。",
