      "stem": "閱讀八年級學生 Eason 於「10 月 15 日（週四）晚上 9:00」寫下的英文日記，請整合「過去時間、連接詞 Before／After 與未來計畫」，排定下列四個事件由「最早發生」到「最晚發生（含明日計畫）」的正確時間順序：\n[Thursday, October 15 — 9:00 p.m.]\nWhat a busy week! My cousin Jerry arrived in Taipei from Kaohsiung yesterday morning. Before he took the train north, my aunt baked a box of pineapple cakes for him to bring to us. Tonight at seven, Mom cooked beef noodles for Jerry, and we ate together happily. Tomorrow afternoon, Dad is going to drive all of us to Yehliu Geopark after I finish my math quiz at school!\n\n• 事件甲：Aunt baked a box of pineapple cakes.\n• 事件乙：Jerry arrived in Taipei.\n• 事件丙：Eason finishes his math quiz at school.\n• 事件丁：Dad drives the family to Yehliu Geopark.",
