        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱六書辨識原則（Ab-IV-3、4-IV-2）：① 象形：畫成其物，隨體詰詘（純具體物象）；② 指事：視而可識，察而見意（純抽象符號，或在象形字基礎上加抽象指事符號標示部位）；③ 會意：比類合誼，以見指撝（合二字以上之義成新義，無聲符）；④ 形聲：以事為名，取譬相成（形旁表意、聲旁表音，占漢字八成以上，且有左形右聲、上形下聲、內形外聲等多種方位）。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 判定甲組（山、魚、門）：直接描摹山峰、游魚、雙扇門的具體實物外貌，獨體不可拆，屬於「象形」。\n2. 判定乙組（本、末、刃）：分別在象形字「木」的下部加一橫指明「樹根（本）」、上部加一橫指明「樹梢（末）」，以及在象形字「刀」的鋒口加一點指明「刀鋒（刃）」。因含有標示抽象位置的指事符號，並非純粹物象，屬於「指事」。\n3. 判定丙組（休、信、采）：「人」依「木」為休息（休）、「人」之「言」當誠實（信）、「爪（手）」在「木」上表摘取（采），皆由兩部件意義會合而成，無表音偏旁，屬於「會意」。\n4. 判定丁組（晴、聞、露）：「晴」左形（日）右聲（青），「露」上形（雨）下聲（路）；而「聞」本義為聽見，部首與意義核心在內部的「耳（形符）」，外部的「門（ㄇㄣˊ）」則提供讀音線索（古音門與聞同屬文部，鼻音聲母相轉），屬於「內形外聲」的「形聲字」！故正確選項為 (A)。",
