        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱漢字六書架構（Ab-IV-3、4-IV-2）：① 前四書（象形、指事、會意、形聲）為「造字法」，後二書（轉注、假借）不產生新字體，為「用字法」；②「假借」定義為「本無其字，依聲託事」——語言裡有某個抽象虛詞或代詞（如自己、不要）卻沒專字，便借用既有同音字頂替；③「轉注」定義為「建類一首，同意相受」——同一部首、意義相同相近而可互訓。",
