      "title": "【會考語法句型原型改編】漢語四大句型核心判準與文言代詞「是」字防誤判",
      "stem": "七年級語法課整理出五個古今文句，檢驗同學對「漢語四大句型（敘事句、有無句、表態句、判斷句）」與「『是』字詞性」的掌握程度：\n【甲】「雨後的山嵐格外清新柔美。」\n【乙】「天下沒有白吃的午餐。」\n【丙】「母親是她人生路上最溫柔的燈塔。」\n【丁】「老奶奶在巷口親切地招呼放學的孩子。」\n【戊】「今法如此而更重之，『是』法不信於民也！」（司馬遷〈張釋之執法〉）\n關於上述五句的「句型結構」與「『是』字語法功能」判讀，下列何者完全正確？",
