      "stem": "閱讀下列甲、乙兩段關於「乘船受箭」的文本，判斷下列關於文體性質、敘事視角與人物刻畫的分析，何者正確？\n\n【甲】這時候大霧漫天，江上連面對面都看不清。孔明下令把船頭朝西，船尾朝東，一字兒擺開，又叫船上軍士一邊擂鼓，一邊大聲吶喊。魯肅吃驚地說：「如果曹兵出來，怎麼辦？」孔明笑著說：「霧這樣大，曹操一定不敢派兵出來。我們只管飲酒取樂，天亮了就回去！」曹操聽見鼓聲和吶喊聲，果然下令說：「重霧迷江，彼軍忽至，必有埋伏，切不可輕動。可撥水軍弓弩手亂箭射之。」（改寫自羅貫中《三國演義》第四十六回）\n\n【乙】權乘大船來觀公（曹操）軍，公使弓弩亂發，箭著其船，船偏重將覆，權因迴船，復以一面受箭，箭均船平，乃還。（節錄自陳壽《三國志・吳主傳》裴松之注引《魏略》）",
