        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據中國古典小說史與小說技法（Ad-IV-4）：\n1. 流變脈絡：魏晉六朝文言「筆記小說」（非章回體）➔ 唐代文言「傳奇」➔ 宋元白話「話本」➔ 明清長篇「章回小說」（元末明初《三國演義》與《水滸傳》、明代《西遊記》、清代《紅樓夢》）。\n2. 「情節伏筆」指前文先行交代某項能力或物件，為後文關鍵情節預作鋪墊。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 判讀【甲】與【乙】：甲文言簡意賅，出自南朝宋劉義慶編撰的志人筆記小說《世說新語》，屬隨筆記錄名士言行的短篇文言筆記，絕非章回體；乙文寫孫悟空在太上老君八卦爐中因躲在巽宮（風位有煙無火）薰成「火眼金睛」，出自明代吳承恩神魔章回小說《西遊記》，此設定正是後文保護唐僧西天取經時能一眼看穿白骨精等妖魔變化的關鍵「情節伏筆」。\n2. 判讀【丙】與【丁】：丙文出自清代曹雪芹《紅樓夢》第三回賈寶玉初見林黛玉的肖像描寫；丁文出自元末明初施耐庵《水滸傳》第八回「魯智深大鬧野豬林」，魯智深一路暗中跟隨保護林沖（「在林子裡聽你多時」），展現「粗中有細、俠肝義膽」。\n3. 綜合核對，選項 (A) 對《世說新語》體制與《西遊記》伏筆功能的分析完全正確，故選 (A)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：丙文描寫體弱多愁、眉目含情的《紅樓夢》女主角林黛玉，並非《三國演義》貂蟬；丁文魯智深預判董超、薛霸會在僻靜野豬林下手而暗中埋伏救人，且僅擊飛水火棍震懾公人一路護送林沖至滄州，展現的是「粗中有細、智勇雙全」而非有勇無謀誤殺公人。\n• 選項 (C) 錯誤：成書時代《西遊記》（乙，明代中葉）早於《紅樓夢》（丙，清代乾隆年間），正確順序應為「甲 ➔ 丁 ➔ 乙 ➔ 丙」；且甲為文言筆記小說，明清白話章回小說係由宋元「話本」發展而來。\n• 選項 (D) 錯誤：丙文正是古典小說中最著名的「外貌神態肖像描寫」（無一字對話）；甲文則以極凝練的對話與動作（「公大笑樂」）勾勒人物才情，毫無長篇心理獨白。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版九年級總複習必考「四大名著＋《世說新語》＋《聊齋誌異》＋《儒林外史》」七書總表：先分清楚「文言短篇（世說、聊齋）」與「白話章回（三國、水滸、西遊、紅樓、儒林）」，即可秒殺一半誘答選項！"
