        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱應用文書信與信封規約（Be-IV-2、6-IV-2）：\n1. 對師長規範：提稱語用「道鑒／尊鑒／鈞鑒」，結尾請安語用「敬請 教安／道安」，學生自稱「受業／門生／學生」，末啟詞用「敬上／謹上」。\n2. 直式信封規範：右路寫收件地址，中路寫「收件人姓氏職稱 ＋ 啟封詞（師長用道啟／鈞啟／安啟）」，左路寫寄件地址＋「緘／謹緘」；中路絕不可寫「敬啟」（意指請收信人恭敬拆開，極不禮貌）！",
