        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：頭號段考殺手陷阱！沒注意到 `Toby,` 後面的逗號，把 Toby 誤當第三人稱主詞填了 `carries`；`boxs` 漏加 e；`please are` 未用原形 be；且複數 `these` 與單數 `bottle` 衝突。\n• 選項 (C) 錯誤：分詞 `carrying` 不能單獨當祈使句動詞；形容詞 careful 前誤填助動詞 `do`；複數 `those` 與單數 `bottle` 衝突。\n• 選項 (D) 錯誤：不定詞 `to carry` 不能當獨立祈使句主要動詞；複數 `those` 後誤接單數 `box`；且 `please is` 未將 be 動詞還原為原形。",
