        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據五大基本句型核心判準（Ad-IV-1）：① 副詞（`loudly`）與介系詞片語（`in the hall`、`all night`）僅為修飾語，剃除後不計入句型骨幹；② 感官連綴動詞（`taste` 嚐起來）後接形容詞作「主詞補語（C）」，構成 `S + V + C`；③ 授與動詞（`sent` 寄給／送給）後接「人（間接受詞 IO）＋物（直接受詞 DO）」，因「人 ≠ 物」，屬於 `S + V + O + O`；④ 不完全及物動詞（`kept` 使……保持……）後接「受詞 O ＋形容詞受詞補語 OC」，因補語用來描述受詞的狀態（`our feet` 處於 `comfortable` 狀態），屬於 `S + V + O + C`。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 拆解句子 ①：`All the children (S) + laughed (V)`，`loudly`（大聲地，方式副詞）與 `in the hall`（地點副詞片語）皆為修飾語，骨幹為 `S + V`（完全不及物）。\n2. 拆解句子 ②：`Those fresh strawberries (S) + taste (連綴 V) + very sweet (主詞補語 C)`，sweet 形容草莓本身很甜，骨幹為 `S + V + C`（不完全不及物）。\n3. 拆解句子 ③：`Aunt Kelly (S) + sent (V) + the twin brothers (IO) + two wool hats (DO)`，雙胞胎兄弟 ≠ 兩頂毛帽，骨幹為 `S + V + O + O`。\n4. 拆解句子 ④：`The warm soup (S) + kept (V) + our feet (O) + comfortable (OC)`（all night 為時間修飾語），形容詞 comfortable 補充說明受詞 `our feet`（雙腳）整晚舒適溫暖的狀態，骨幹為 `S + V + O + C`。\n5. 故分析完全正確者為 (D)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：誤將修飾動作方式的副詞 `loudly` 當成名詞受詞（O），忽略 laugh 為不及物動詞。\n• 選項 (B) 錯誤：誤把連綴動詞 `taste`（嚐起來……）當成及物動作動詞，忽略 `sweet` 為形容詞主詞補語（C）而非受詞。\n• 選項 (C) 錯誤：看到動詞後面有兩塊成分就一概歸為雙受詞 S + V + O + O，忽略 `comfortable` 是形容詞（不能當直接受詞），專門補充說明 `our feet` 的狀態。",
