      "title": "【會考基礎句構原型題】校隊隊長專訪：頻率副詞「be 後動前」、形容詞 late 與 can 原形鐵律",
      "stem": "閱讀以下校刊小記者介紹籃球校隊隊長 Ray 的短文，依據「頻率副詞語序規則」與「情態助動詞 can 用法」，選出語法完全正確的選項：\nCaptain Ray is a great model for everyone on our school basketball team. He ______ friendly and patient with new players, and he ______ late for 6:30 a.m. morning training. Even under strong defense, Ray ______ three-point shots accurately with either hand!",
