      "stem": "閱讀以下新生參觀學校閱覽室時的對話，依據「There is / There are 存在句疑問倒裝、並列名詞就近一致原則、不可數名詞搭配與禁寫 There have」規則，選出語法完全正確的選項：\nMia: Wow, this reading corner looks so cozy! ______ any computer desks for students to search for online books here?\nGuide: Yes! Over by the window, ______ a large wooden table and six comfortable chairs. Also, ______ cold drinking water in the hallway, so you can bring your own bottle!",
