        "【第 1 步：審題定位 · 題眼與已知】對話描述閱覽室空間設施的存在狀況：① 第一格為詢問「這裡有沒有任何電腦桌？」的存在疑問句，後方緊接複數名詞 `any computer desks`；② 第二格描述窗邊存在「一張大木桌與六張舒適椅子（`a large wooden table and six comfortable chairs`）」，緊鄰空格的第一個名詞是單數 `a large wooden table`；③ 第三格描述走廊有冰飲用水，緊鄰空格的名詞 `cold drinking water` 核心字 `water` 為不可數名詞。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱存在句核心規範（Ad-IV-1）：① 表達某處「有（存在）」某物只能用 `There is / There are`，絕對禁止混入 `have / has`（嚴禁寫 `There have / There has` 或 `Do there have`）；② 疑問句將 be 動詞移至 there 前方，複數名詞 `desks` 配 `Are there`；③ 當 `there be` 後接 `A and B` 並列名詞時，動詞單複數遵守**就近一致原則（Proximity Rule）**——只看緊貼在空格後方的第一個名詞（`a large wooden table` 為單數，必用 `there is`）；④ 不可數名詞（`water`、`milk`、`money`）一律視為單數，搭配 `there is`。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 第一格：存在疑問句＋複數名詞 `any computer desks` → 填 `Are there`。\n2. 第二格：緊貼空格的第一個名詞為單數 `a large wooden table`（不受後方 and six comfortable chairs 影響），依就近一致原則填 `there is`。\n3. 第三格：緊貼空格的 `cold drinking water` 為不可數名詞，視為單數，填 `there is`。\n4. 三格依序為 `Are there; there is; there is`，故正確選項為 (C)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：全數掉入母語負遷移陷阱，自創中式英文錯句 `Do there have` 與 `there has`（切記：`sb. have/has sth.` 主詞是人或物，而 `There is/are` 表空間存在，兩套系統絕不混搭！）。\n• 選項 (B) 錯誤：第二格掉入「數學加法陷阱」——把一張木桌加六張椅子算成七樣家具就選了 `there are`，違反存在句只看緊鄰第一個名詞 `a large wooden table` 的就近一致鐵律！\n• 選項 (D) 錯誤：第一格單數 `Is there` 誤配複數 `desks`；第三格複數 `there are` 誤配不可數名詞 `water`。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林與南一段考最愛把第二格反過來考對照組：`There IS a table and six chairs.` vs `There ARE six chairs and a table.`——意思完全一樣，但誰排在第一個位置，誰就決定前面是 `is` 還是 `are`！只要拿筆圈出空格後面的第一個名詞，1 秒破題零失誤！"
