        "【第 2 步：破題關鍵 · 課綱概念與核心公式】本題總體檢單元四大高頻防線（Ad-IV-1）：① 頻率副詞置於一般動作動詞之前（`usually swims`、`never drinks`），且**頻率副詞不是助動詞**，當主詞為第三人稱單數（Owen / he）時，後方一般動詞即使前面有 `never / sometimes`，依然必須加 `-s`！② `never` 本身即為 0% 否定詞，不可再加 `doesn't`；③ `can` 後必接原形動詞；④ 針對 `Is Owen often...?` 作肯定簡答時，頻率副詞必須移至句尾 be 動詞之前寫成 `Yes, he often is.`（絕不可寫 `Yes, he is often.`）。",
