        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱句構（Ad-IV-1）：① 感官動詞「hear / see / watch / notice + 受詞 + 原形 V（全程）或 V-ing（正在進行）」，主動句絕不可接 to V；② 漸進比較「越來越……」遇多音節形容詞（confident）用「more and more + 原級」（前面不加 the）；③ 成正反比連動句型「越……就越……」固定公式為「The + 比較級 + S1 + V1, the + 比較級 + S2 + V2」。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 判定空格 (1)：heard 為感官動詞，Chloe 主動拉小提琴且強調老師站在教室外當下聽見正在練習的片段，填現在分詞 practicing（或原形 practice 亦可，檢視選項刪去 to practice 與過去分詞 practiced）。\n2. 判定空格 (2)：confident 為三音節形容詞，「變得越來越有自信」須寫作 become more and more confident（不加定冠詞 the）。\n3. 判定空格 (3)：後半句為「, the less nervous you will feel」，前半句首必對稱使用「The + 比較級」，即「The more you focus on the music itself（你越專注於音樂本身）」。綜合三格，故正確選項為 (D)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：空格 (1) 犯下感官動詞主動句大忌「heard sb. to V」（誤與 ask/want sb. to V 混淆），且空格 (3) 漏掉雙重比較句首必備的定冠詞 The。\n• 選項 (B) 錯誤：空格 (1) 誤填過去式／過去分詞 practiced（Chloe 是主動拉琴而非被練習），且空格 (2) 杜撰錯誤片語 much and much。\n• 選項 (C) 錯誤：把兩種比較句型混搭成四不像！漸進比較「more and more + 原級」前方不可加 the，而空格 (3)「As more as」更是將原級 as...as 與比較級錯誤拼湊。",
