        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱比較結構與圖表轉譯能力（Ad-IV-1、3-IV-6）：① 原級同等比較「A + be + (just) as + 形容詞原級 + as + B」表 A 與 B 程度相同，否定「not as + 原級 + as」中間絕不可放 -er 比較級；② 三者比較「of the three / in the table」須用「the + 最高級（-est / most）」；③「The + 比較級..., the + 比較級...」前後皆須用比較級而非最高級。",
