        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱授予動詞與使役動詞句構（Ad-IV-1）：① 授予動詞將「物」置於「人」之前時，「花費勞力烹飪／烘焙／購買／製作（bake, cook, make, buy）」強調為了對方利益，介系詞必用 for；「書寫／寄送／給予／展示（write, send, give, show, lend）」強調訊息或物品方向轉移至對方，介系詞必用 to；② 使役動詞「have / make / let + 人（主動）+ 原形動詞 V」，嚴禁加 to。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 判定空格 (1)：bake（烘焙）屬於花時間與心力親手製作糕點給媽媽享用，物前人後須搭配介系詞 for（baked a lemon cheesecake for Mom）。\n2. 判定空格 (2)：write（寫信／寫卡片）屬於將文字心意傳達給對方，物前人後須搭配表方向對象的介系詞 to（wrote a thank-you card to her）。\n3. 判定空格 (3)：Dad had me... 中 had 為使役動詞 have 的過去式，「我（me）」是主動去擦客廳窗戶的人，受詞補語必須使用原形動詞 clean。綜合三格為「for; to; clean」，故正確選項為 (A)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：將 bake（配 for）與 write（配 to）的介系詞完全顛倒，且空格 (3) 受後句「ask ... to put」干擾，誤在使役動詞 had me 後方加上不定詞 to clean。\n• 選項 (C) 錯誤：誤以為所有母親節禮物動作一律配 for 而寫出 wrote a card for her（除非指代媽媽捉刀寫給別人，否則寫給媽媽本人必用 to），且使役動詞 had me 後誤接現在分詞 cleaning。\n• 選項 (D) 錯誤：bake 誤配 to，且空格 (3)「had me cleaned」變成「把我自己送去給別人清洗」的荒謬被動語意（唯有受詞是窗戶 Dad had the windows cleaned 時才用過去分詞表被動）。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版皆將「make/buy/cook/bake/get + 物 + for + 人」編為口訣，並將「had me clean（使役原形）」與「asked my brother to put（一般動詞 to V）」同句對比。代回語意檢驗，三格皆精準無誤！"
