      "stem": "閱讀以下校刊小記者訪問外籍英語教師 Mr. Miller 的專訪紀錄，選出最符合現在完成式時間標記與經驗副詞文法的選項填入空格 (1)、(2)、(3)：\nStudent: Welcome to our school in Hsinchu, Mr. Miller! How long have you lived in Taiwan?\nMr. Miller: Let me see—I have lived in Taiwan ____(1)____ I graduated from college in 2019, so that's ____(2)____ more than six years!\nStudent: Wow, your Chinese must be great! Have you ____(3)____ taken the forest train up to Alishan to watch the sunrise?\nMr. Miller: Not yet! My wife has gone to Kaohsiung on a business trip this week, and we plan to visit Alishan together next month.",
