        "【第 1 步：審題定位 · 題眼與已知】檢視對話時間軸與語氣：小記者以「How long have you lived...?」詢問持續至今的時間。第 (1) 格後接完整過去簡單式子句「I graduated from college in 2019（2019 年大學畢業那個時間起點）」；第 (2) 格後接時間長度「more than six years（超過六年這段期間）」；第 (3) 格位於現在完成式疑問句「Have you ____ taken...?」助動詞與過去分詞之間，詢問過往至今是否曾有此經驗。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱現在完成式語法（Ad-IV-1、3-IV-6）：①「現在完成式（have/has + p.p.）+ since + 過去時間點／過去簡單式子句（S + V-ed）」標示動作起始點；②「現在完成式 / 時段補充 + for + 數量化時間長度」標示持續總長；③ 詢問對方「是否曾經……」經驗時，疑問句中搭配副詞 ever（Have you ever + p.p....?），回答尚未體驗時常用 Not yet。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 判定空格 (1)：後方「I graduated from college in 2019」為過去簡單式子句，代表「自從 2019 年大學畢業以來」的明確起點，唯一能引導過去式子句銜接現在完成式的連接詞為 since。\n2. 判定空格 (2)：後方「more than six years（六年多）」為累計時間區間長度，須搭配介系詞 for。\n3. 判定空格 (3)：「Have you ever taken the forest train...?（你曾經搭過森林小火車上阿里山嗎？）」詢問人生經驗，且自然銜接下句回答「Not yet!」，故填 ever。綜合三格，故正確選項為 (C)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：將 for（接一段時間）與 since（接起點或過去式子句）完全顛倒，for 作為介系詞後絕不可接過去式子句 I graduated...。\n• 選項 (B) 錯誤：空格 (2) 誤在時間長度「more than six years」前放 since（若要用 since 須改寫為 since six years ago）；且空格 (3) 記者初次禮貌詢問經驗不宜預設負向 never。\n• 選項 (D) 錯誤：from 單獨使用不搭配現在完成式表「自從……至今」（須用 since），during 後接特定事件名詞（如 during the summer vacation）而不接計量時段 more than six years，且 yet 在疑問句中應置於句尾而非句中。",
