        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 Ad-IV-1 綜合語法檢核準則：① 使役動詞 make / let + 受詞 + 原形 V；ask + 受詞 + (not) to V；② give / lend 表方向轉移，物前人後必配介系詞 to（give/lend + 物 + to + 人）；③ 瞬間動作動詞（buy 購買、borrow 借入）不可直接配 for + 一段時間表持續（須改用狀態動詞 have had / have kept）；④ 表「去過某地幾次（twice）」經驗必用 has been to，不可用表「去了還沒回來」的 has gone to。",
