      "knowledgeAudit": "108 課綱（Ad-IV-1、3-IV-6）要求學生運用名詞子句與間接問句進行得體禮貌的資訊詢問與觀點陳述，並透過附加問句達成互動確認。標點符號亦隨主句決定（I don't know where he lives. 句尾為句號；Could you tell me where he lives? 因主句 Could you... 為疑問句故句尾為問號）。"
