        "requiredKnowledge": "回推必備知識：當 wh- 疑問句嵌入另一主句（如 Can you tell me... / Nobody knows... / Please check...）成為受詞名詞子句時，必須由倒裝疑問語序改為「wh- 疑問詞 + 主詞 + 動詞」直述語序：① 含 be 動詞或情態助動詞（can, will, should）者，直接將 S 與 be/情態助動詞交換位置（where is he → where he is）；② 含疑問助動詞 do / does / did 者，消去助動詞並將時態與單複數還給一般動詞（where does he live → where he lives；when did she leave → when she left）；③ 若 who / what 本身即為子句主詞（who broke the window），語序原本即為 S + V 不必更動。",
