        "requiredKnowledge": "回推必備知識：① 基本原則「前肯後否（縮寫 n't）、前否後肯」；若直述句含 never, seldom, hardly, rarely, few, little, nothing, nobody 等否定詞，全句視為「否定句」，附加問句必用「肯定」！② 附加問句主詞必須是代名詞：this / that / V-ing / to V / everything / nothing 一律代換為 it；these / those / everyone / nobody 代換為 they；there be 句型保留 there；③ 回答附加問句時，英文嚴格依「客觀事實」決定：事實有做就答「Yes, S + 助動詞」，事實沒做就答「No, S + 助動詞 + n't」（中文常翻成「對，他沒做」，切勿誤選 Yes, he doesn't）。",
