        "requiredKnowledge": "回推必備知識：① that 引導「確定陳述事實」的名詞子句（作受詞時 that 常可省略，但作主詞 That he won is true 不可省略）；② whether / if 表「是否」，用於主句帶有不確定、懷疑或詢問語氣（wonder, ask, don't know, not sure）之後，且同樣採用直述語序「whether/if + S + V」；注意句尾緊接 or not（whether... or not）、作介系詞受詞（worry about whether...）或置於句首作主詞時，只能用 whether 而不可用 if；③ 祈使句附加問句：「Let's + V（咱們一起……吧）」固定配「shall we?」；一般肯定／否定祈使句（含 Let us 表請求允許我們）則配「will you?」。",
