        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 Ad-IV-1 間接問句與祈使句附加問句規則：① 原直接問句「Whom/Who does this smartwatch belong to?」改為間接問句時，必須刪除疑問助動詞 does，並將第三人稱單數「-s」還原給本動詞 belong →「whom/who this smartwatch belongs to」；② 原直接問句「When did the owner drop it?」改為間接問句時，必須刪除疑問助動詞 did，並將過去式變化還原給本動詞 drop →「when the owner dropped it」（注意短母音+單子音須重複字尾 p 加 ed）；③「Let's + 原形 V（咱們一起……吧）」的附加問句固定為「shall we?」。",
