        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據先秦寓言閱讀與儒家思維（Ad-IV-4、Cc-IV-1、5-IV-2）：\n1. 寓言結構公式：假託象徵性故事（喻體）➔ 映射抽象人生／治國哲理（寓意），不可拘泥於表層農事。\n2. 關鍵文言字義：「閔」通「憫」（憂慮）；「揠」為拔起；「芒芒然」為疲倦貌；「病」古義為「疲倦、勞累」（非生病）；「趨」為快步走；「舍」通「捨」（放棄）；「耘」為除草耕耘。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 拆解喻體因果：宋國人擔憂禾苗長不高而親手把苗往上拔高，疲憊不堪地回家炫耀「今天累壞了，我幫禾苗長高了」，兒子快步趕去田裡查看，禾苗卻因根部離土早已枯死。\n2. 提煉雙層寓意：孟子在文末同時批判兩種極端錯誤態度——第一種是「以為無益而舍之者，不耘苗者也」（認為修養無益便徹底放棄不管，如種田不除草）；第二種是「助之長者，揠苗者也」（急於求成、強行拔高，不僅無益反而造成傷害）。唯有持之以恆正常耕耘、循序漸進方為正道。\n3. 核對四個選項，選項 (A) 完整涵蓋喻體、雙向警戒與循序漸進寓意，故選 (A)。",
