      "stem": "閱讀《莊子・養生主》節選，判斷下列關於本文寓言寓意與思想流派的詮釋，何者正確？\n\n庖丁釋刀對曰：「臣之所好者，道也，進乎技矣。始臣之解牛之時，所見無非牛者；三年之後，未嘗見全牛也。……依乎天理，批大郤，導大窾，因其固然，技經肯綮之未嘗，而況大軱乎！良庖歲更刀，割也；族庖月更刀，折也。今臣之刀十九年矣，所解數千牛矣，而刀刃若新發於硎。彼節者有間，而刀刃者無厚；以無厚入有間，恢恢乎其於遊刃必有餘地矣！」文惠君曰：「善哉！吾聞庖丁之言，得養生焉。」\n【注】郤：通「隙」，空隙。窾：骨節空處。肯綮：筋骨結合緊密處。大軱：大骨頭。族庖：一般的廚師。硎：磨刀石。",
