      "steps": [
        "【第 1 步：審題定位 · 題眼與已知】題幹並置三則先秦思想名段：【甲】〈守株待兔〉（出自《韓非子・五蠹》）、【乙】〈買櫝還珠〉（出自《韓非子・外儲說左上》）、【丙】〈兼愛〉（出自《墨子・兼愛中》）。考查法家變法實效思維、墨家兼愛非攻主張，以及文言字義與寓言象徵本質。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱法家與墨家核心思維（Cc-IV-1、5-IV-2）：\n1. 法家（韓非子）：反對儒墨復古守舊（「不期修古，不法常可」），主張法律制度須隨時代環境改變（「因時制宜」），並重實效、反對形式主義浮華包裝。\n2. 墨家（墨子）：主張不分血緣親疏遠近的無差別博愛（「兼愛：視人之國若視其國」）以消弭攻伐戰爭（「非攻：諸侯相愛則不野戰」），異於儒家由親及疏的差等仁愛。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 解析【甲】：野兔奔跑（「走」＝疾跑）撞樹根折頸純屬偶然，農夫放下農具（「耒」）死守樹樁妄想再撿兔子終遭恥笑；韓非子在末句直指寓意：「今欲以先王之政，治當世之民，皆守株之類也」，痛批死守古代先王舊制治理現代百姓的迂腐，主張治國必須因時變法。\n2. 解析【乙】：楚國珠寶商過度裝飾木蘭珠盒（「櫝」），導致鄭國買家只買下華麗外盒卻退還真正珍貴的寶珠（韓非子原意亦藉此諷刺言辭過於華美反而掩蓋治國實質學說），批判取捨失當、重表象而輕實質的本末倒置。\n3. 解析【丙】：連用三個「視人之……若視其……」推導出不野戰、不相篡、不相賊，屬標準墨家「兼愛、非攻」思想。故選項 (B) 完全正確，選 (B)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：古文中「走」為「奔跑」（緩慢行走古文稱「行」或「步」——若兔子慢慢散步豈會撞斷脖子死亡！），且韓非子明確批判效法先王舊政是「守株之類」的愚蠢行為。\n• 選項 (C) 錯誤：「視人之國若視其國、視人之身若視其身」打破血緣國界差等，是「墨家（墨子）」的兼愛非攻主張；儒家講究「親親而仁民，仁民而愛物」的差等次序，道家則主張清靜無為而非積極倡導諸侯互愛互助。\n• 選項 (D) 錯誤：先秦諸子寓言中的宋人、楚人、鄭人皆為服務哲理論辯而設的象徵性喻體，並非紀傳體正史人物，閱讀寓言的核心正是在提煉背後的思想主旨。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】南一、康軒、翰林九年級總複習必背先秦四家秒判口訣：「孔子孟子講仁義（親疏有別），老子莊子順自然（無用逍遙），韓非講法重變革（守株買櫝），墨子兼愛反戰爭（視人若己）」！"
      ]
