      "typeName": "會考高頻：現代記敘抒情散文核心意象營造、動作感官細節與映襯・倒反・層遞修辭張力",
      "frequency": "近七年會考（109～115）年年必考現代散文長文題組（占 4～6 題） · 八下段考現代文學核心主軸",
