      "clues": "題幹為一篇融合童年記憶、親情羈絆或日常器物的現代白話散文，詢問「文中反覆出現的某物件（如橘子、桂花、紙船、舊毛衣）象徵何種情感」、「作者如何不直接說愛卻展現深情」或辨析「映襯、倒反（反語）、層遞」等修辭在語境中的真實意涵。",
