        "【第 1 步：審題定位 · 題眼與已知】題幹並置描寫同一對象（臺灣東部黑潮海域瓶鼻海豚）的兩篇異質文本：【甲】作者親乘船隻出海與海豚四目相交並引發人海關係省思；【乙】詳列瓶鼻海豚學名、分類、體長體重、分布與回聲定位機制的客觀條目。核心檢驗「自然寫作／海洋文學 vs 科普百科說明文」的界線。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱臺灣自然與海洋書寫三層閱讀（Bb-IV-3、5-IV-2）：\n1. 自然寫作（含海洋文學）必備三要素：親臨現場的感官「觀察」＋ 生態倫理與生命省思「觀點」＋ 文學修辭「表達」；絕不等同枯燥的動植物百科說明。\n2. 科普說明文則以準確、客觀、中性知識傳遞為目的，不帶個人情感投射。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 三層剖析【甲】文：\n   • 觀察層：記錄黑潮深藍湧浪、海豚破浪躍出、銀灰背鰭晨光弧線及隔水四目相交的真實海事現場體驗。\n   • 觀點層：省思引擎轟鳴的粗魯，提出「大海不是等待人類征服的獵場，而是教導島嶼子民遼闊與謙卑的導師」之生態共生觀點。\n   • 表達層：將海豚眼神擬人化設問，並將大海譬喻為導師，情感真摯深沉，屬典型臺灣海洋文學（廖鴻基海洋書寫精神）。\n2. 剖析【乙】文：使用學名、公尺、公斤、科學解剖名詞（額隆、回聲定位），語氣客觀平實，屬生物科普百科說明文。\n3. 綜合比對，選項 (A) 完全精確，故選 (A)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：完全顛倒自然寫作與百科圖鑑的定義！若只有客觀數據而無現場感官體驗與生命倫理省思，只能稱為科普說明或圖鑑，不能稱為自然文學寫作。\n• 選項 (C) 錯誤：甲文明確寫道「放下魚叉與傲慢」、「大海從來不是等待人類征服的獵場」，核心思想是「敬畏與謙卑共生」，恰與「人定勝天、征服獵捕」相反。\n• 選項 (D) 錯誤：乙文通篇為客觀科學事實陳述，毫無主觀抒情、友誼歌頌或神話想像。",
