        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據在地與自然書寫三層閱讀（Bb-IV-3、5-IV-2）：\n1. 觀察：踏查現場今昔地貌與物種存續細節（水丁香、白腹秧雞、蓋斑鬥魚消失 ➔ 細蟌找不到泥縫水草產卵）。\n2. 觀點：反思人類以單一「整齊無泥」審美標準進行水泥化開發，實則摧毀微棲地多樣性。\n3. 表達：今昔映襯、譬喻（「客廳地板」喻指人工去自然化）、擬人（「原住鄰居」尊稱本土野生生物）與激問（反詰，答案在反面）。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 檢核「觀察」層：三面光（溝底與兩側皆封死水泥）工程切斷了土壤與水體連結，導致水草、水鳥與魚類棲地消失，細蟌焦躁盤旋卻無處產卵。\n2. 檢核「觀點」與「表達」層：面對居民只重人類便利的「乾淨好走」，作者以「沒有泥土氣味的客廳地板」精妙譬喻過度人工化的荒謬，將本土動植物稱為「陪伴島嶼千百年的原住鄰居」，並以文末激問直指此種「假美化」實為「將本土生物逐出家門」的生態剝奪。\n3. 綜合三層檢驗，選項 (B) 分析絲絲入扣，故選 (B)。",
