        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】翰林、康軒、南一三版九年級自然散文與近年會考環境議題長文，十篇有八篇結尾都用「激問句」收束！讀完問句立刻反問自己：「作者前面蹲在地上心痛的是誰？」就能一秒抓準作者真正的生態觀點！"
