      "strategy": "時間介系詞守住「三階＋兩例外」：精確鐘點配 at、特定單日與星期配 on、月季年長區間配 in；但①「特定某天的早午晚（如 on Sunday morning / on a snowy evening）」核心落在那一天故必改用 on，② 時間詞前一旦出現 this / that / next / last / every 則「絕對不加任何介系詞」！空間移動看幾何維度：二維平面（馬路、橋面）橫越用 across，三維空間內部（隧道、森林、公園大門、窗戶）穿過用 through，一維線條（河岸、街道）順行用 along。",
