      "stem": "細讀下方「陽光河濱公益路跑（Sunshine Charity Run）」活動宣傳單，選出最符合時間介系詞規則與特定日期修飾例外的選項填入空格 (1)、(2)、(3)：\n┌─────────────────────────────────────────────────────────────┐\n│ 🏃 2026 Sunshine Charity Run — Run for Children's Smiles!   │\n│ • Our city first started this charity run ____(1)____       │\n│   October, 2018, and over 5,000 runners join every autumn.  │\n│ • This year's race will take place ____(2)____ a breezy     │\n│   Sunday morning, November 15th.                            │\n│ • All runners must gather at the Riverside Square ____(3)____│\n│   6:15 a.m. sharp for the warm-up exercise!                 │\n└─────────────────────────────────────────────────────────────┘",
