      "title": "【會考條件邏輯原型改編】校園環保社淨灘行前通知：First Conditional 與 unless 條件判讀",
      "stem": "閱讀以下學校環保社發布的「週六海岸淨灘活動行前通知」，選出最符合未來可能發生之真實條件句（First Conditional）時態與連接詞邏輯的選項填入空格 (1) 與 (2)：\nDear Student Volunteers,\nThank you for signing up for Saturday's beach clean-up! According to the latest weather report, a strong front is moving toward northern Taiwan. If it ____(1)____ heavily tomorrow morning, we will move the event to next Saturday for everyone's safety. In addition, the tour bus will leave the school gate at 7:30 a.m. sharp—nobody can get on the bus ____(2)____ they hand in the signed parent consent form first!",
