        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱核心條件副詞子句規則（Ad-IV-1、3-IV-6）：① 在「可能發生的未來條件句（First Conditional）」中，if 引導的條件副詞子句必須以「現在簡單式」代替未來式（主詞 it 配單數動詞 rains），絕不可在條件子句內放 will；② 條件連接詞辨義：if 表「如果」，unless 表「除非／如果不（＝ if ... not）」，須代入前後句檢驗准許搭車的邏輯。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 判定空格 (1)：If 引導表「如果明天早上下大雨」的未來真實條件副詞子句，依「主將從現」原則刪去 will rain，主詞 it 搭配現在簡單式單數動詞 rains。\n2. 判定空格 (2)：比對前後句邏輯——「沒有人可以上校車，『除非（如果不）』他們先繳交家長同意書」，即「if they do NOT hand in the form, nobody can get on the bus」，故必填否定條件連接詞 unless。\n3. 綜合 (1) 與 (2) 結果為「rains; unless」，故正確選項為 (C)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：同時掉入兩大陷阱！空格 (1) 看見 tomorrow morning 就直譯中文「如果明天將會下雨」而誤填 will rain；空格 (2) 誤填 if 導致句意變成「如果繳交家長同意書，就沒有人能上車」的荒謬反話。\n• 選項 (B) 錯誤：空格 (1) 雖正確使用現在簡單式 rains，但空格 (2) 未看清主句主詞為否定詞 nobody，誤填 if 造成因果徹底相反。\n• 選項 (D) 錯誤：空格 (2) 雖正確判斷出「除非 unless」，但空格 (1) 違反「if 條件副詞子句現在代未來」鐵律而誤填 will rain。",
