        "【第 2 步：破題關鍵 · 課綱概念與核心公式】區分真實性兩套公式：①【段考延伸】與現在事實相反之假設語氣：「If + 主詞 + were / 過去式動詞, 主詞 + would / could / might + 原形 V」，其中 be 動詞不論第一、三人稱單數，正式書面考試一律使用 were（If I were you）；②【課綱核心】未來可能發生之真實條件句（First Conditional）：主句為「he will surely forgive you」，故 if 條件子句必用「現在簡單式（apologize）」表未來。",
