        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 Ad-IV-1 關係子句四大檢核準則：① 先行詞同時含「人與動物（singer and dog）」時，不可偏袒人用 who 或偏袒動物用 which，強制使用「that」；② 當介系詞留在關係子句尾（listened to）時，受格關代（which / that）可合法省略，且子句內不得再加受詞 it；③ 介系詞後嚴禁接 that；④ 受格關代已取代受詞，子句內嚴禁重複出現受詞代名詞（it / them）。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 拆解目標句結構：主詞先行詞為單數名詞「The charity song」，括號標出形容詞子句「[(which/that) you listened to] last night」。\n2. 執行還原檢查：將先行詞還原至子句尾得「you listened to [the charity song] last night」——不及物動詞 listen 搭配的介系詞 to 完整保留在子句尾，未漏掉 to，也未多寫贅字 it；而受格關代 which / that 置於主詞 you 前方依法省略，完全合規！\n3. 核對主要動詞：刪去形容詞子句後，主句骨幹為「The charity song ... was written by two ninth-grade students」，單數主詞配被動過去式 was written 完全吻合，故正確選項為 (B)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：先行詞為「The blind singer（盲人歌手，人）and his guide dog（導盲犬，動物）」，只看鄰近名詞 guide dog 就誤填 which，違反「人＋動物強制使用 that」鐵律（應改為 that performed）。\n• 選項 (C) 錯誤：將「the wooden guitar (which/that) Leo practiced with」的介系詞 with 前移後，竟寫出違規結構「with that」（介系詞後嚴禁接 that，應改為 with which）。\n• 選項 (D) 錯誤：犯下段考翻譯與選擇題最高頻的「受詞代名詞贅字錯誤」！關係代名詞 which 本身就已經代表先行詞 The cookies 作 baked 的受詞，後面卻又重複寫出「baked them」，必須把多餘的 them 刪除。",
