      "stem": "閱讀以下關於「都市校園屋頂農園降溫計畫」的素養克漏字短文，根據空格前後句的因果、否定替代與語意轉折關係，選出最恰當的轉折詞組合填入空格 (1)、(2)、(3)：\nIn crowded modern cities, dark concrete roofs absorb huge amounts of heat from the sun during summer. ____(1)____, top-floor classrooms and apartments often feel like hot ovens in July, forcing people to run air conditioners all day long. Last spring, Sunny Junior High School decided not to cover its old roof with ordinary gray paint; ____(2)____, students and teachers planted sweet potato leaves and mint in wooden boxes across the roof. At first, several parents worried that heavy typhoon rain might wash mud into the building's water pipes. ____(3)____, after the school installed simple filter nets under each box, the pipes stayed completely clean, and temperatures in top-floor classrooms dropped by nearly 3°C!",
